const NOT_SOURCE = [
  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
];
export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));

/** 1-based line number of `index` in `text`. */
export const lineOf = (text, index) => text.slice(0, index).split('\n').length;

/**
 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
 * brackets), or null when the source is unbalanced — a half-written file should
 * make a check say nothing, never guess. String and template literals are skipped
 * so a bracket inside "a(b)" can't be read as syntax.
 */
export function balanced(src, open) {
  let depth = 0;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (c === '"' || c === "'" || c === '`') {
      const quote = c;
      for (i += 1; i < src.length; i++) {
        if (src[i] === '\\') { i += 1; continue; }
        if (src[i] === quote) break;
      }
      continue;
    }
    if (c === '{' || c === '[' || c === '(') depth += 1;
    else if (c === '}' || c === ']' || c === ')') {
      depth -= 1;
      if (depth === 0) return src.slice(open, i + 1);
    }
  }
  return null;
}

const STRING_LITERAL = /'([^'\\]*)'|"([^"\\]*)"/g;

/**
 * Every `const|let|var NAME = { … }` object literal in `src` whose properties map
 * a key to an ARRAY OF STRING LITERALS — the shape a phrase table takes. Returns
 * `{ name, index, body, arms }`, `arms` being `[{ key, phrases: [{ text, index }] }]`
 * with indices relative to `src`.
 *
 * An arm whose array holds anything other than string literals (a nested array, an
 * identifier, a computed value) is skipped rather than guessed at, and a table with
 * fewer than two such arms is not a lexicon at all — one arm cannot collide.
 */
export function phraseTables(src) {
  const DECL = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*\{/g;
  const out = [];
  let m;
  while ((m = DECL.exec(src))) {
    const bodyStart = DECL.lastIndex - 1;
    const body = balanced(src, bodyStart);
    if (body === null) continue; // unbalanced source: say nothing
    const PROP = /(?:^|[,{])\s*(?:'([^']*)'|"([^"]*)"|([A-Za-z_$][\w$]*)|(\d+))\s*:\s*\[/g;
    const arms = [];
    let p;
    while ((p = PROP.exec(body))) {
      const key = p[1] ?? p[2] ?? p[3] ?? p[4];
      const arrStart = PROP.lastIndex - 1;
      const arr = balanced(body, arrStart);
      if (arr === null) continue;
      // Only an array that is *nothing but* string literals is a phrase list.
      const residue = arr.replace(STRING_LITERAL, '').replace(/[[\],\s]/g, '');
      if (residue.length) continue;
      const phrases = [];
      STRING_LITERAL.lastIndex = 0;
      let s;
      while ((s = STRING_LITERAL.exec(arr))) {
        phrases.push({ text: s[1] ?? s[2], index: bodyStart + arrStart + s.index });
      }
      if (phrases.length) arms.push({ key, phrases });
    }
    if (arms.length >= 2) out.push({ name: m[1], index: m.index, body, arms });
  }
  return out;
}

// How a phrase table is consumed when a duplicate phrase can silently disappear:
// the table is walked arm by arm and each phrase is either INVERTED into a lookup
// keyed by the phrase (`EXACT.set(p, …)`, `byPhrase[p] = key`) or MATCHED against
// the utterance in table order (`phrases.includes(norm)`). Both resolve a phrase
// listed twice by position alone — last writer wins, or first arm wins — with
// nothing anywhere saying which was meant.
const WALKS = (name) => new RegExp(
  `Object\\s*\\.\\s*(?:entries|keys)\\s*\\(\\s*${name}\\s*\\)|\\bin\\s+${name}\\b`,
  'g',
);
const RESOLVES = /\.\s*(?:set|includes|has|indexOf)\s*\(|\[\s*[A-Za-z_$][\w$]*\s*\]\s*=[^=]/;

/**
 * Is `table` walked in `src` as a phrase→intent lexicon — i.e. does a walk over it
 * feed a phrase-keyed lookup or an in-order match? A table nobody walks is data
 * somebody reads by key, and a repeated string in it is not an ambiguity.
 */
export function isWalkedAsLexicon(src, table) {
  const walks = WALKS(table.name);
  let m;
  while ((m = walks.exec(src))) {
    if (RESOLVES.test(src.slice(m.index, m.index + 400))) return true;
  }
  return false;
}

import { finding, stripComments, isSource, lineOf, phraseTables, isWalkedAsLexicon } from './lib.mjs';

// A spoken interface recognises intents by their SURFACE PHRASES: a table mapping
// each intent to every wording a user might say for it, walked to build a
// phrase-keyed lookup (`EXACT.set(phrase, intent)`) or matched arm by arm against
// the utterance. Both shapes resolve a phrase listed under two intents by
// POSITION — the last arm to write the key wins, or the first arm to be scanned
// wins — and nothing in the source says which was meant.
//
// That is a bug with no symptom at the site of the mistake. The table still
// compiles, every test that says the phrase still passes (against whichever intent
// happened to win), and the loss shows up only as a user saying a perfectly listed
// phrase and getting the other command — the hardest kind of voice bug to report,
// because the user cannot see the table and the developer cannot hear the room.
// These tables grow by accretion — every live mishearing a session turns up gets
// appended to the arm it was heard for — so the collision usually arrives months
// after both arms were written, in a diff that only adds one line.
//
// Deliberately scoped to a phrase listed under two DIFFERENT intents. The same
// phrase twice within one arm is a redundancy that resolves to the intent it was
// always going to resolve to; it costs nothing and this rule has no opinion on it.
// And a table nobody walks as a lexicon is left alone entirely: a synonym or
// expansion map read by key legitimately repeats its values (a homophone set names
// every word in it, under every word in it), and firing there would be exactly the
// false alarm that teaches a team to ignore a check.
//
// Comments are stripped first, so a commented-out arm is not a live arm.

const rule = {
  id: 'intent-phrases-unique',
  severity: 'blocking',
  description: 'No surface phrase is listed under two intents',
  doc: '.claudinite/local/packs/voice-dialog/RULES.md',
  why: 'a phrase listed under two intents is resolved by table order, not by intent — the losing intent becomes unreachable through that wording and nothing anywhere reports it',

  run(ctx) {
    const out = [];
    for (const file of ctx.files) {
      if (!isSource(file)) continue;
      const raw = ctx.read(file);
      if (raw === null || !raw.includes('[')) continue;
      const src = stripComments(raw);
      for (const table of phraseTables(src)) {
        if (!isWalkedAsLexicon(src, table)) continue;
        const owner = new Map(); // phrase → first arm's key
        for (const arm of table.arms) {
          for (const phrase of arm.phrases) {
            const first = owner.get(phrase.text);
            if (first === undefined) {
              owner.set(phrase.text, arm.key);
              continue;
            }
            if (first === arm.key) continue; // repeated inside one arm: harmless
            out.push(finding(rule, {
              file,
              line: lineOf(src, phrase.index),
              what: `${table.name} lists the phrase "${phrase.text}" under both "${first}" and "${arm.key}" — whichever the walk reaches last (or first) silently wins`,
              fix: `give the phrase to exactly one intent and delete it from the other, or — if both readings are genuinely meant — resolve it in context rather than in the table (ask which was meant, or key it on the mode the speaker is in)`,
            }));
          }
        }
      }
    }
    return out;
  },
};

export default rule;

import intentPhrasesUnique from './intent-phrases-unique.mjs';

// voice-dialog — turning what a speech recognizer heard into an intent or a piece
// of content, and turning the app's answer back into something worth listening to.
// The lexicon of surface phrases, the normalization every match runs on, what to
// do with an n-best list, when to ask instead of guess, and how much to say.
//
// Every rule here judges the design of a spoken interface and holds for any app
// with one — a voice assistant, an IVR, a dictation surface, an accessibility
// mode — and the check's scan is repo-shape agnostic (see lib.mjs `isSource`) so
// it cannot pass vacuously green somewhere laid out differently. It lives locally
// only because the mounted canon has no home for this facet: the canon packs
// cover MV3 mechanics (chrome-extension), release (chrome-extension-release),
// node, github-actions, tidy-repo, and the spec/requirements discipline
// (spec-driven-product, executable-requirements) — none of them says anything
// about speech at all.
//
// The two sibling local packs bound it on either side: `browser-speech` owns the
// speech APIs themselves (the recognizer's lifecycle, mic capture, TTS delivery,
// error taxonomies) and `host-page-adaptation` owns the page the answers are typed
// into. This pack owns what happens between them — the language layer, which is
// pure and knows about neither. Declared by hand as `local/voice-dialog` in
// .claudinite-checks.json.
export default {
  id: 'voice-dialog',
  ruleRoutingGuidance: {
    belongs: 'designing a spoken dialog — intent lexicons, transcript normalization, n-best candidates, ambiguity, what the app says back',
    excludes: 'the speech APIs and mic themselves — local/browser-speech; driving the page the answer lands in — local/host-page-adaptation',
  },
  marker: null,
  detect: null,
  prose: 'RULES.md',
  worldRules: [
    intentPhrasesUnique,
  ],
};

// Red-first fixtures for the voice-dialog pack's check.
//
// The rule is exercised four ways: it must FIRE on violating sources, stay QUIET
// on clean ones, stay quiet on the shapes its parsing exists to spare (which are
// then confirmed to fire against the naive alternative), and stay quiet on the
// repo's real extension/src/ tree. That last case is what makes the pack
// shippable — a check that only ever saw its own fixtures is a check nobody has
// confronted with real code.
//
// Runs in the project's own vitest (see the .claudinite/local/packs include in
// vitest.config.js) and imports nothing from the gitignored canon mount, so it
// works in CI exactly as it does locally.

import { describe, test, expect } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

import pack from './pack.mjs';
import { isSource, stripComments, phraseTables } from './lib.mjs';
import intentPhrasesUnique from './intent-phrases-unique.mjs';

// A check context over a literal file map — the same {files, read} surface the
// engine's runner passes, with nothing else the rule is allowed to touch.
const ctxOf = (files) => ({
  files: Object.keys(files),
  read: (f) => (f in files ? files[f] : null),
});

const run = (rule, files) => rule.run(ctxOf(files));

describe('voice-dialog pack manifest', () => {
  test('is a hand-declared local pack whose rules are all wired', () => {
    expect(pack.id).toBe('voice-dialog'); // must equal the directory name
    expect(pack.detect).toBeNull();
    expect(pack.marker).toBeNull();
    expect(pack.prose).toBe('RULES.md');
    expect(pack.worldRules.map((r) => r.id).sort()).toEqual(['intent-phrases-unique']);
  });
});

// The scan must be repo-shape agnostic: a rule that only ever looks under one
// project's source root matches nothing — and passes vacuously green — in a repo
// laid out differently, which is exactly the bug these cases exist to prevent.
describe('source scope', () => {
  test('accepts source under any layout, in JS and TS alike', () => {
    for (const file of [
      'extension/src/matching/commands.js',
      'src/dialog/intents.ts',
      'app/lib/lexicon.tsx',
      'packages/voice/grammar.mjs',
      'assistant.cjs',
    ]) expect(isSource(file), file).toBe(true);
  });

  test('rejects test scaffolding, fixtures and vendored code wherever they sit', () => {
    for (const file of [
      'extension-test/unit/matching.test.js',
      'extension-test/fixtures/fake-nyt/fake-app.js',
      'src/lexicon.spec.ts',
      'test/intents.js',
      'node_modules/x/index.js',
      'dist/content.js',
      'README.md',
    ]) expect(isSource(file), file).toBe(false);
  });
});

// The two shapes in which a duplicated phrase silently disappears: inverted into a
// phrase-keyed lookup (last writer wins) and matched arm by arm (first arm wins).
const INVERTED_DUP = `
  const PHRASES = {
    next: ['next', 'skip', 'pass'],
    clear: ['clear', 'erase', 'delete'],
    undo: ['undo', 'undue', 'delete'],
  };
  const EXACT = new Map();
  for (const [intent, phrases] of Object.entries(PHRASES)) {
    for (const p of phrases) EXACT.set(p, { intent });
  }
  export const parse = (text) => EXACT.get(text) ?? null;
`;

const SCANNED_DUP = `
  const CONTROLS = {
    done: ['done', 'finished', 'enter'],
    cancel: ['cancel', 'never mind', 'enter'],
  };
  export function control(norm) {
    for (const [control, phrases] of Object.entries(CONTROLS)) {
      if (phrases.includes(norm)) return control;
    }
    return null;
  }
`;

// Quiet: the same phrase repeated INSIDE one arm resolves to the intent it was
// always going to resolve to. Redundant, not ambiguous.
const REPEAT_WITHIN_ARM = `
  const PHRASES = {
    next: ['next', 'skip', 'next'],
    clear: ['clear', 'erase'],
  };
  const EXACT = new Map();
  for (const [intent, phrases] of Object.entries(PHRASES)) {
    for (const p of phrases) EXACT.set(p, { intent });
  }
`;

// Quiet: a table nobody walks as a lexicon. A synonym/expansion map read BY KEY
// legitimately names the same word under several keys — a homophone set is the
// canonical case — and firing here is precisely the false alarm that teaches a
// team to ignore a check.
const SYNONYM_MAP_READ_BY_KEY = `
  const HOMOPHONES = {
    SEA: ['SEE', 'C'],
    SEE: ['SEA', 'C'],
    C: ['SEA', 'SEE'],
  };
  export const homophonesOf = (word) => HOMOPHONES[word] ?? [];
`;

describe('intent-phrases-unique', () => {
  test('fires on a phrase listed under two intents in an inverted lexicon', () => {
    const found = run(intentPhrasesUnique, { 'src/commands.js': INVERTED_DUP });
    expect(found.map((f) => f.rule)).toEqual(['intent-phrases-unique']);
    expect(found[0].what).toContain('"delete"');
    expect(found[0].what).toContain('clear');
    expect(found[0].what).toContain('undo');
    expect(found[0].severity).toBe('blocking');
    expect(found[0].line).toBe(7); // the losing arm's copy, not the first one
  });

  test('fires on a phrase listed under two intents in an arm-by-arm match', () => {
    const found = run(intentPhrasesUnique, { 'src/spelling.ts': SCANNED_DUP });
    expect(found.map((f) => f.rule)).toEqual(['intent-phrases-unique']);
    expect(found[0].what).toContain('"enter"');
  });

  test('is quiet on a lexicon whose phrases are all distinct', () => {
    const clean = INVERTED_DUP.replace("'undo', 'undue', 'delete'", "'undo', 'undue'");
    expect(run(intentPhrasesUnique, { 'src/commands.js': clean })).toEqual([]);
  });

  test('is quiet on a phrase repeated inside one arm', () => {
    expect(run(intentPhrasesUnique, { 'src/commands.js': REPEAT_WITHIN_ARM })).toEqual([]);
  });

  test('is quiet on a synonym map read by key rather than walked as a lexicon', () => {
    expect(run(intentPhrasesUnique, { 'src/homophones.js': SYNONYM_MAP_READ_BY_KEY })).toEqual([]);
  });

  test('is quiet on a commented-out arm', () => {
    const commented = `
      const PHRASES = {
        next: ['next', 'skip'],
        // clear: ['clear', 'skip'],
        clear: ['clear', 'erase'],
      };
      const EXACT = new Map();
      for (const [intent, phrases] of Object.entries(PHRASES)) {
        for (const p of phrases) EXACT.set(p, { intent });
      }
    `;
    expect(run(intentPhrasesUnique, { 'src/commands.js': commented })).toEqual([]);
  });

  test('skips test scaffolding and vendored code', () => {
    expect(run(intentPhrasesUnique, {
      'src/__tests__/commands.test.js': INVERTED_DUP,
      'node_modules/voicelib/index.js': INVERTED_DUP,
    })).toEqual([]);
  });
});

// A violating fixture failing and a clean one passing only proves the shipped
// check is correct — it says nothing about whether the parsing it does was
// NECESSARY. So run the quiet fixtures against the naive alternative the parsing
// exists to avoid, and confirm they would wrongly fire there.
describe('the parsing earns its complexity', () => {
  // The naive check: any object-of-string-arrays with a string appearing twice
  // anywhere in it — no per-arm scoping, no "is this walked as a lexicon?" gate.
  const naiveFires = (source) => {
    const src = stripComments(source);
    for (const table of phraseTables(src)) {
      const seen = new Set();
      for (const arm of table.arms) {
        for (const phrase of arm.phrases) {
          if (seen.has(phrase.text)) return true;
          seen.add(phrase.text);
        }
      }
    }
    return false;
  };

  test('the naive alternative wrongly fires on the quiet fixtures', () => {
    expect(naiveFires(REPEAT_WITHIN_ARM)).toBe(true);
    expect(naiveFires(SYNONYM_MAP_READ_BY_KEY)).toBe(true);
  });

  test('and the real rule still catches both violations', () => {
    expect(naiveFires(INVERTED_DUP)).toBe(true);
    expect(naiveFires(SCANNED_DUP)).toBe(true);
  });
});

// The corpus the rule was discovered against. It must stay quiet here — and this
// repo really does ship the shapes the rule judges (three walked phrase tables in
// two files), so the silence is evidence the rule reaches real code rather than
// passing over it.
describe("this repo's own extension source", () => {
  const ROOT = process.cwd();
  const sourceFiles = (dir, out = []) => {
    for (const name of readdirSync(dir)) {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) sourceFiles(p, out);
      else out.push(relative(ROOT, p).split(sep).join('/'));
    }
    return out;
  };
  const files = Object.fromEntries(
    sourceFiles(join(ROOT, 'extension/src')).map((f) => [f, readFileSync(join(ROOT, f), 'utf8')]),
  );

  test('really does contain walked phrase lexicons for the rule to judge', () => {
    const walked = Object.entries(files)
      .filter(([f]) => isSource(f))
      .flatMap(([, src]) => phraseTables(stripComments(src)).map((t) => t.name));
    expect(walked).toEqual(expect.arrayContaining(['PHRASES', 'CHOICE_PHRASES', 'CONTROLS']));
  });

  test('is quiet', () => {
    expect(run(intentPhrasesUnique, files)).toEqual([]);
  });
});

